(function(){
 'use strict';
 window.WBAIUI=function(ctx){
  const {esc:e,icon,heading,badge,toast}=ctx;
  let info=null,tab='text',busy=false,result=null,statusError='',drafts={text:'',image:''};const results=new Map();
  const repaint=()=>{if(['#connections','#radar'].includes(location.hash))ctx.render();};
  async function request(url,options){const response=await fetch(url,options);const value=await response.json();if(!response.ok){const error=new Error(value.error||'本机服务未完成请求');error.attempts=value.attempts||[];error.code=value.code;throw error;}return value;}
  async function reload(){try{info=await request('/api/ai/status');for(const r of info.recent||[])if(r.ok)results.set(r.requestId,r);statusError='';}catch{statusError='连接状态暂时无法读取，请确认本机服务已启动。';}repaint();}
  function date(value){try{return new Intl.DateTimeFormat('zh-CN',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));}catch{return '';}}
  function attemptsHTML(attempts){return (attempts||[]).length?`<details class="ai-diagnostics"><summary>查看本次线路记录</summary>${attempts.map(a=>`<p><strong>${e(a.name||a.provider)}</strong> · ${a.status==='ok'?'成功':e(a.message||'未完成')}</p>`).join('')}</details>`:'';}
  function actionsHTML(value){return value?.kind==='text'&&value.ok?`<div class="ai-save-actions"><button class="small-button" data-action="ai-save-topic" data-id="${e(value.requestId)}">存为选题</button><button class="small-button" data-action="ai-save-task" data-id="${e(value.requestId)}">把小任务加入今天</button><button class="small-button" data-action="ai-save-idea" data-id="${e(value.requestId)}">存为想法</button></div>`:'';}
  function outputHTML(value){
   if(!value)return `<div class="ai-empty">${icon(tab==='text'?'message-square':'clapperboard')}<h3>${tab==='text'?'把一个问题，变成可用的下一步。':'先用一张图，验证你的想法。'}</h3><p>填写上方内容后点击生成。这里会保留本机结果，刷新页面可从最近记录回看。</p></div>`;
   if(value.failed)return `<div class="ai-error" role="alert"><strong>这次未完成</strong><p>${e(value.error)}</p>${attemptsHTML(value.attempts)}<p class="ai-secondary">${value.code==='input'?'本次输入已在本机拦截，没有发送模型请求。':'如果提示状态不明，请先核对服务商记录，再决定是否重新提交。'}</p></div>`;
   const meta=`<div class="ai-result-meta">${badge(value.usedFallback?'已使用备用':'使用主线路',value.usedFallback?'amber':'teal')}<span>${e(value.providerName)} · ${e(value.model)}</span><time>${date(value.createdAt)}</time></div>${value.storageWarning?`<p class="ai-warning" role="alert">${e(value.storageWarning)}</p>`:''}`;
   if(value.kind==='text')return `${meta}${value.source?.type==='news'?'<p class="ai-secondary">模型未联网，只基于公开标题和摘要；重要事实请核对原文。</p>':''}<div class="ai-generated-text">${e(value.text)}</div>${value.truncated?'<p class="ai-warning">本次输出达到长度上限，请缩小问题后再生成。</p>':''}${attemptsHTML(value.attempts)}${actionsHTML(value)}`;
   const imageUrl=/^\/api\/ai\/image\/[a-f0-9]{24}$/.test(value.imageUrl||'')?value.imageUrl:'';
   const extension=['png','jpg','webp'].includes(value.format)?value.format:'png';
   const oneK=Number(value.width)>=1024&&Number(value.height)>=1024&&Number(value.width)===Number(value.height);
   return `${meta}<div class="ai-image-preview">${imageUrl?`<img src="${imageUrl}" alt="AI生成结果，实际尺寸${Number(value.width)}乘${Number(value.height)}" loading="lazy">`:''}</div><div class="ai-image-caption"><span>实际 ${Number(value.width)} × ${Number(value.height)}${oneK?'（服务商最低 1K 档）':''}</span>${imageUrl?`<a class="small-button" href="${imageUrl}" download="工作台AI图片.${extension}">${icon('download')}下载原图</a>`:''}</div>${oneK?'':`<p class="ai-warning">这次实际图片未达到正方形且两边至少1024像素的1K档要求。请核对原件和服务商设置。</p>`}${attemptsHTML(value.attempts)}`;
  }
  function providerHTML(provider){
   return `<article class="ai-provider"><div class="ai-provider-title"><h3>${e(provider.name)}</h3>${badge(provider.id==='primary'?'优先使用':'失败时备用',provider.id==='primary'?'blue':'gray')}</div>${['text','image'].map(kind=>{const cap=provider.capabilities[kind];const last=(info?.recent||[]).filter(r=>r.kind===kind).flatMap(r=>r.attempts||[]).find(a=>a.provider===provider.id);return `<div class="ai-capability"><span>${kind==='text'?'文字':'生图'}</span><div><strong>${e(cap.model)}</strong><small>${!cap.configured?'尚未填写密钥':last?last.status==='ok'?'最近一次请求成功':'最近一次未完成，查看结果中的线路记录':'密钥已读取，等待实际调用'}</small></div></div>`;}).join('')}<details class="ai-diagnostics"><summary>接口地址与说明</summary>${['text','image'].map(kind=>`<p>${kind==='text'?'文字':'生图'}<code>${e(provider.capabilities[kind].endpoint)}</code></p>`).join('')}<p>按服务商和能力分别配置，不统一添加版本路径。密钥由本机服务读取，页面不显示。</p></details></article>`;
  }
  function view(){
   const locked=busy||!!info?.busy;
   const recent=info?.recent||[];
   const selected=result?.kind===tab?result:recent.find(r=>r.kind===tab&&r.ok);
   return `<div class="ai-page-intro"><div><span class="ai-eyebrow">我的 AI 工作区</span><h2>从一个问题，开始推进。</h2><p>文字梳理思路，图片验证想法。由你点击生成，使用主线路，明确失败时再尝试备用。</p></div><button class="outline-button" data-action="ai-reload">${icon('compass')}重新读取连接状态</button></div>${statusError||info?.notice?`<p class="ai-warning" role="status">${e(statusError||info.notice)}</p>`:''}<div class="ai-workspace"><section class="panel ai-composer"><div class="tab-bar ai-tabs" role="group" aria-label="AI能力">${[['text','文字助手'],['image','图片生成']].map(([id,label])=>`<button type="button" data-action="ai-tab" data-value="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${icon(id==='text'?'message-square':'clapperboard')}${label}</button>`).join('')}</div><form id="ai-${tab}-form"><label class="form-field" for="ai-prompt">${tab==='text'?'这次想解决什么问题？':'你想生成什么画面？'}<textarea id="ai-prompt" name="prompt" required rows="5" maxlength="${tab==='text'?4000:1200}" placeholder="${tab==='text'?'例如：把一个AI工具试用过程，整理成适合小红书的内容提纲。请只使用我输入的事实。':'例如：一只蓝色陶瓷茶壶，米色桌布，左侧自然光，简洁方形画面，没有文字或标志。'}">${e(drafts[tab])}</textarea></label>${tab==='text'?`<div class="ai-presets"><span>从这里开始</span>${[['topic','想一个内容方向'],['steps','拆成执行步骤'],['news','解释一条资讯']].map(([id,label])=>`<button type="button" data-action="ai-preset" data-id="${id}" ${locked?'disabled':''}>${label}</button>`).join('')}</div>`:'<p class="ai-secondary">模型 gpt-image-2 · 每次 1 张 · 1K 档，服务商实际返回约 1254 × 1254。</p>'}<div class="ai-submit-row"><p>点击会调用你的中转额度；只发送当前输入，不附带项目、知识库或聊天。</p><button class="primary-button" type="submit" ${locked||!info?.providers?.some(p=>p.capabilities[tab].configured)?'disabled':''}>${icon(tab==='text'?'message-square':'clapperboard')}${locked?'正在生成…':tab==='text'?'生成文字':'生成一张图片'}</button></div></form><section class="ai-output" aria-label="生成结果" aria-live="polite" aria-busy="${locked}">${locked?'<div class="ai-loading"><span></span><strong>正在等待模型结果</strong><p>生图可能需要数分钟。等待期间不要重复提交；离开页面不会自动取消已发出的请求。</p></div>':outputHTML(selected)}</section></section><aside class="ai-side"><section class="ai-local-note">${icon('lock-keyhole')}<div><h3>密钥留在本机</h3><p>修改本机填写表并保存后，重新读取状态即可。页面不接收密钥，也不会自动运行后台任务。</p><small>模型生成不代表内容已核实，重要事实请核对原始来源。这里的模型调用不附带联网搜索。</small></div></section>${heading('连接线路','按文字和生图分别使用各站接口。')}<div class="ai-providers">${info?.providers?.map(providerHTML).join('')||'<p class="ai-secondary">正在读取本机连接配置…</p>'}</div></aside></div><section class="panel ai-recent">${heading('最近的本机结果','只保存在这台电脑，可点开回看。')}<div class="ai-recent-list">${recent.length?recent.map(r=>`<button class="ai-history-row" data-action="ai-history" data-id="${e(r.requestId)}"><span>${icon(r.kind==='text'?'message-square':'clapperboard')}<strong>${r.kind==='text'?'文字':'图片'}</strong><small>${r.ok?e(r.providerName):r.status==='processing'?'执行状态待核对':'上次请求未完成'}</small></span><span>${r.ok?'查看结果':'查看记录'} ${date(r.createdAt)} ${icon('chevron-right')}</span></button>`).join(''):'<p class="ai-secondary">还没有页面生成记录。输入一个小问题，开始第一次尝试。</p>'}</div></section><div class="ai-maintenance"><button class="text-button" data-action="backup-state">${icon('download')}备份任务与备注</button><button class="text-button" data-action="recheck-library">${icon('book-open')}重新核对资料入口</button><span>生成图片与AI记录单独保存在本机资料目录，任务备份不包含它们。</span></div>`;
  }
  function handleClick(el){const action=el.dataset.action;
   if(['ai-save-topic','ai-save-task','ai-save-idea'].includes(action)){const value=results.get(el.dataset.id);if(!value){toast('这条结果尚未读取，请重新读取连接状态');return true;}if(action==='ai-save-topic')ctx.saveTopic?.(value);if(action==='ai-save-task')ctx.saveTask?.(value);if(action==='ai-save-idea')ctx.saveIdea?.(value);return true;}
   if(action==='ai-tab'){tab=el.dataset.value==='image'?'image':'text';repaint();return true;}
   if(action==='ai-reload'){reload();return true;}
   if(action==='ai-preset'){const examples={topic:'请帮我设计3个AI实操内容方向，面向外贸运营同行。每个方向写清真实问题、可演示的小任务与验证证据；不编造客户结果，不确定的信息标明待核实。',steps:'请把下面的目标拆成每天约1小时能推进的小步骤。每一步写清输入、动作和完成证据。目标：',news:'请根据我粘贴的公开原文，解释发生了什么、对工作有什么帮助，以及一个20分钟的小试用任务。不要把推测当事实。原文：'};drafts.text=examples[el.dataset.id]||'';tab='text';repaint();document.querySelector('#ai-prompt')?.focus();return true;}
   if(action==='ai-history'){const old=info?.recent.find(r=>r.requestId===el.dataset.id);if(old){tab=old.kind;result=old.ok?old:{kind:old.kind,failed:true,error:old.error||'上次请求执行状态尚未确认，请先核对服务商记录',attempts:old.attempts};repaint();document.querySelector('.ai-output')?.scrollIntoView({block:'nearest',behavior:'auto'});}return true;}
   return false;
  }
  function handleInput(target){if(target.id==='ai-prompt')drafts[tab]=target.value;}
  function handleSubmit(form){if(!['ai-text-form','ai-image-form'].includes(form.id))return false;
   if(busy||info?.busy){toast('已有生成正在进行，请等待结果');return true;}
   const kind=form.id==='ai-text-form'?'text':'image';const prompt=String(new FormData(form).get('prompt')||'').trim();if(!prompt)return true;drafts[kind]=prompt;busy=true;repaint();
   request('/api/ai/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Action':'manual'},body:JSON.stringify({prompt,requestId:crypto.randomUUID()})}).then(value=>{result=value;results.set(value.requestId,value);toast(value.usedFallback?'生成完成，已使用备用线路':'生成完成');}).catch(error=>{result={kind,failed:true,code:error.code,error:error.message,attempts:error.attempts||[]};}).finally(async()=>{busy=false;await reload();repaint();});return true;
  }
  async function explainNews(news){if(busy||info?.busy){toast('已有AI请求正在进行，请等待完成');return;}const requestId=crypto.randomUUID();busy=true;repaint();ctx.modal('让AI解释这条公开资讯',`<div data-news-explain-request="${requestId}"><p class="dialog-lead">${e(news.title)}</p><p>正在解释，只发送服务端公开缓存中的标题、来源、日期、摘要和链接。</p><p class="quiet-note">模型未联网；等待期间不要重复点击。</p></div>`,'公开资讯解释');try{const value=await request('/api/ai/explain-news',{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Action':'manual'},body:JSON.stringify({newsId:news.id,requestId})});results.set(value.requestId,value);result=value;if(document.querySelector('#dialog').open&&document.querySelector('[data-news-explain-request="'+requestId+'"]'))ctx.modal('AI解释：'+news.title,outputHTML(value),'公开资讯解释');else toast('资讯解释已完成，可在AI工作区回看');}catch(error){if(document.querySelector('#dialog').open&&document.querySelector('[data-news-explain-request="'+requestId+'"]'))ctx.modal('资讯解释未完成',outputHTML({failed:true,kind:'text',code:error.code,error:error.message,attempts:error.attempts||[]}),'公开资讯解释');else toast('资讯解释未完成：'+error.message);}finally{busy=false;await reload();}}
  return {view,handleClick,handleSubmit,handleInput,init:reload,isBusy:()=>busy||!!info?.busy,explainNews};
 };
})();
